mapper.select:
select orders.*, type.name as typeName, type.img as typeImg, hotel.name as hotelName, user.name as userName
from orders
left join type on orders.type_id = type.id and type.deleted = 0
left join hotel on orders.hotel_id = hotel.id and hotel.deleted = 0
left join user on orders.user_id = user.id and user.deleted = 0


    orders.deleted = 0
     and orders.id = #{id}
     and orders.order_id like concat('%', #{orderId}, '%')
     and orders.status = #{status}
     and orders.type_id = #{typeId}
     and orders.hotel_id = #{hotelId}
     and orders.user_id = #{userId}
     and orders.time = #{time}
     and orders.in_time = #{inTime}
     and orders.out_time = #{outTime}
     and orders.days = #{days}
     and orders.price = #{price}


order by orders.id desc

